// Pseudo-JS read-through pattern with fallback
async function getMetadata(key) {
  const cached = await evcache.get(key)
  if (cached) return cached

  // Backoff guard: avoid thundering herd with singleflight or lock
  await singleflight.acquire(key)
  try {
    // re-check cache after acquiring singleflight
    const cached2 = await evcache.get(key)
    if (cached2) return cached2

    // read durable store
    const row = await cassandra.query('SELECT * FROM metadata WHERE key=?', [key])
    if (row) {
      // populate cache with appropriate TTL profile
      await evcache.set(key, row, ttlForKey(key))
    }
    return row
  } finally {
    singleflight.release(key)
  }
}

